"""A tiny, security-minded CSV validation rules engine.

Rules are plain JSON dicts. Supported shapes:

1. Conditional rule (a ``when`` guard narrows which rows the ``check`` applies to):

   {"when": {"col": "country", "equals": "US"},
    "check": {"col": "zip", "regex": "^[0-9]{5}(-[0-9]{4})?$"}}

2. Cross-column comparison (value of one column >= value of another):

   {"check": {"col": "end_date", "gte_col": "start_date"}}

3. Arithmetic-free expression comparing exactly two columns:

   {"check": {"expr": "discount_cents <= total_cents"}}

The expression parser accepts ONLY the grammar::

    expr := IDENT WS OP WS IDENT
    OP   := '<=' | '>=' | '==' | '<' | '>'

Anything else (literals, arithmetic, attribute access, function calls,
chained comparisons, imports...) is rejected with ValueError. There is no
eval/exec anywhere in this module; comparisons are done with operator
functions from the stdlib `operator` module.

Row numbers reported in violations are 1-indexed FILE LINE NUMBERS:
the header line is row 1, the first data row is row 2.
"""

from __future__ import annotations

import operator
import re
from datetime import date
from typing import Any, Iterable

__all__ = ["load_rules", "parse_expr", "validate", "Violation", "EvalError"]

# Longest operators first so '<=' is never matched as '<' + '='.
_OPS = {
    "<=": operator.le,
    ">=": operator.ge,
    "==": operator.eq,
    "<": operator.lt,
    ">": operator.gt,
}

# Strict grammar: identifier OP identifier. Nothing else.
_EXPR_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*\s*(<=|>=|==|<|>)\s*[A-Za-z_][A-Za-z0-9_]*$")
_TOKEN_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")


class EvalError(ValueError):
    """Raised when a rule or expression is outside the supported grammar."""


def parse_expr(expr: str) -> tuple[str, str, str]:
    """Parse 'colA OP colB'. Returns (left, op, right).

    Raises EvalError for anything outside the grammar. This is a pure
    regex-based parser -- no eval, no exec, no compile.
    """
    if not isinstance(expr, str):
        raise EvalError(f"expr must be a string, got {type(expr).__name__}")
    stripped = expr.strip()
    if not _EXPR_RE.fullmatch(stripped):
        raise EvalError(
            f"expression {expr!r} rejected: grammar is exactly 'colA OP colB' "
            f"with OP in {sorted(_OPS)}"
        )
    left, op, right = re.split(r"\s*(<=|>=|==|<|>)\s*", stripped, maxsplit=1)
    return left, op, right


def load_rules(path: str) -> list[dict]:
    """Load rules from a JSON file (a single rule or a list of rules)."""
    import json

    with open(path, encoding="utf-8") as fh:
        data = json.load(fh)
    if isinstance(data, dict):
        data = [data]
    if not isinstance(data, list) or not all(isinstance(r, dict) for r in data):
        raise EvalError("rules file must contain a rule object or a list of rule objects")
    return data


def _require_cols(check: dict, cols: Iterable[str], ctx: str) -> None:
    for c in cols:
        if not _TOKEN_RE.fullmatch(c):
            raise EvalError(f"{ctx}: invalid column name {c!r}")


def _compile_check(check: dict) -> dict:
    """Validate a check spec up front; return its normalized form."""
    if not isinstance(check, dict):
        raise EvalError(f"check must be an object, got {type(check).__name__}")

    keys = set(check)
    if keys == {"col", "regex"}:
        _require_cols(check, [check["col"]], "regex check")
        try:
            rx = re.compile(check["regex"])
        except re.error as exc:
            raise EvalError(f"invalid regex {check['regex']!r}: {exc}") from exc
        return {"kind": "regex", "col": check["col"], "rx": rx}

    if keys == {"col", "gte_col"}:
        _require_cols(check, [check["col"], check["gte_col"]], "gte_col check")
        return {"kind": "gte_col", "col": check["col"], "other": check["gte_col"]}

    if keys == {"expr"}:
        left, op, right = parse_expr(check["expr"])
        return {"kind": "expr", "left": left, "fn": _OPS[op], "right": right,
                "op": op, "src": check["expr"]}

    raise EvalError(
        f"unsupported check {sorted(keys)}: expected "
        "{'col','regex'} | {'col','gte_col'} | {'expr'}"
    )


def _compile_rule(rule: dict, index: int) -> dict:
    if not isinstance(rule, dict):
        raise EvalError(f"rule #{index} must be an object")
    if "check" not in rule:
        raise EvalError(f"rule #{index} missing 'check'")
    compiled: dict[str, Any] = {"index": index, "check": _compile_check(rule["check"])}
    when = rule.get("when")
    if when is None:
        compiled["when"] = None
    elif isinstance(when, dict) and set(when) == {"col", "equals"}:
        _require_cols(when, [when["col"]], f"rule #{index} when-clause")
        compiled["when"] = {"col": when["col"], "equals": when["equals"]}
    else:
        raise EvalError(
            f"rule #{index}: 'when' must be exactly {{'col': name, 'equals': value}}"
        )
    extra = set(rule) - {"when", "check"}
    if extra:
        raise EvalError(f"rule #{index} has unsupported keys {sorted(extra)}")
    return compiled


def _when_matches(compiled_when: dict | None, row: dict) -> bool:
    if compiled_when is None:
        return True
    return str(row.get(compiled_when["col"])) == str(compiled_when["equals"])


def _run_check(compiled_check: dict, row: dict, row_no: int) -> str | None:
    """Return a violation message, or None if the row passes."""
    kind = compiled_check["kind"]
    if kind == "regex":
        value = row.get(compiled_check["col"])
        if value is None or compiled_check["rx"].fullmatch(str(value)) is None:
            return (
                f"row {row_no}: column {compiled_check['col']!r} value "
                f"{value!r} does not match {compiled_check['rx'].pattern!r}"
            )
        return None

    if kind == "gte_col":
        raw_a, raw_b = row.get(compiled_check["col"]), row.get(compiled_check["other"])
        try:
            a, b = date.fromisoformat(str(raw_a)), date.fromisoformat(str(raw_b))
        except (TypeError, ValueError):
            return (
                f"row {row_no}: columns {compiled_check['col']!r}/{compiled_check['other']!r} "
                f"values {raw_a!r}/{raw_b!r} are not ISO dates"
            )
        if a < b:
            return (
                f"row {row_no}: {compiled_check['col']} ({a}) is before "
                f"{compiled_check['other']} ({b})"
            )
        return None

    # kind == "expr"
    left, right = compiled_check["left"], compiled_check["right"]
    if left not in row or right not in row:
        return f"row {row_no}: missing column(s) {left!r}/{right!r} for expr"
    try:
        a, b = int(str(row[left])), int(str(row[right]))
    except ValueError:
        return (
            f"row {row_no}: columns {left!r}/{right!r} values "
            f"{row[left]!r}/{row[right]!r} are not integers"
        )
    if not compiled_check["fn"](a, b):
        return (
            f"row {row_no}: expr violated ({compiled_check['src']}): "
            f"{a} !{compiled_check['op']} {b}"
        )
    return None


class Violation(tuple):
    """(rule_index, row_number, message); named access for readability."""

    __slots__ = ()

    def __new__(cls, rule_index: int, row_number: int, message: str):
        return super().__new__(cls, (rule_index, row_number, message))

    @property
    def rule_index(self) -> int:
        return self[0]

    @property
    def row_number(self) -> int:
        return self[1]

    @property
    def message(self) -> str:
        return self[2]


def validate(rows: Iterable[dict], rules: list[dict]) -> list[Violation]:
    """Validate data rows (dicts) against compiled-at-call-time rules.

    Returns a list of Violation tuples sorted by (rule_index, row_number).
    """
    compiled_rules = [_compile_rule(r, i) for i, r in enumerate(rules)]
    out: list[Violation] = []
    for offset, row in enumerate(rows):
        row_no = offset + 2  # header occupies line 1
        for cr in compiled_rules:
            if not _when_matches(cr["when"], row):
                continue
            msg = _run_check(cr["check"], row, row_no)
            if msg is not None:
                out.append(Violation(cr["index"], row_no, msg))
    out.sort(key=lambda v: (v.rule_index, v.row_number))
    return out


def validate_csv(csv_path: str, rules_path: str) -> list[Violation]:
    """Convenience wrapper: validate a CSV file against a JSON rules file."""
    import csv

    with open(csv_path, newline="", encoding="utf-8") as fh:
        rows = list(csv.DictReader(fh))
    return validate(rows, load_rules(rules_path))

